unit_id":"55b46292-0335-5fbc-ab9e-baa44d3bea70","position":1,"is_included":true,"snapshot_id":"66cda81f-6a3a-4c8b-a226-c7169ffd2710","parent_unit_id":"c8804e60-e63d-5f39-92e5-e232ab9f9216","title_override":null,"metadata_override":null,"paragraph_version_id":null},"expected_snapshot":{"id":"66cda81f-6a3a-4c8b-a226-c7169ffd2710","code":"B1_v1.1_STRUCT_DRAFT","name":"Book 1 v1.1 Structural Revision Draft","state":"draft","locked_at":null,"locked_by":null,"created_at":"2026-09-03T03:51:20.430952+00:00","project_id":"707e3ae1-0817-467a-bb42-5401c646151e","updated_at":"2026-09-03T05:50:29.861116+00:00","word_count":217976,"description":"Working draft cloned from B1_v1.0_LOCKED","is_canonical":true,"manifest_hash":"889ae5c488a9e1a4de0576b6de38fc8b1081529681ba17ea5577046227202824","snapshot_kind":"formal","base_snapshot_id":"1f54a517-1921-5d5d-8a16-048597a41a93","is_current_release":false,"is_primary_working":true},"expected_document_md5":"2baab05607d70d29816c425e4a57a1e1","plan":[{"position":1,"unit_id":"adfee7c0-a7cd-51a2-8ae7-c991459b1993","body":"At 07:45 Central European Time, dozens of operators and postdoctoral researchers at the NGC Central Control Center were turning raw telemetry into decisions the machine could execute.","reuse":false,"previous_version_id":"58195185-a376-4af3-9dcb-2352b71b616a","parent_version_ids":["58195185-a376-4af3-9dcb-2352b71b616a","c91899f4-cf6a-49d1-8dbf-b686d952b233"],"old_positions":[1,4],"change_type":"merge"},{"position":2,"unit_id":"ff38d6d2-42e2-5936-9e6c-b0dc2d3d476c","body":"Several kilometers away, beneath the molasse formations of the Geneva basin, the fourteen-thousand-metric-ton NGC-Alpha detector occupied a shielded cavern. Redundant fiber-optic trunks linked it to the surface control infrastructure.","reuse":false,"previous_version_id":"3edd58e8-7c5f-4637-ba6a-944648ea1a8c","parent_version_ids":["3edd58e8-7c5f-4637-ba6a-944648ea1a8c"],"old_positions":[2],"change_type":"rewrite"},{"position":3,"unit_id":"acb54c2a-9ccf-5a6e-bca1-b280e987cf55","body":"Shadowless light washed across the tiered consoles and matte instrument panels. The dry air smelled faintly of warmed polymer insulation and machine oil.","reuse":false,"previous_version_id":"196eeb14-b5fd-4060-a0f5-4ab92421d714","parent_version_ids":["196eeb14-b5fd-4060-a0f5-4ab92421d714"],"old_positions":[3],"change_type":"rewrite"},{"position":4,"unit_id":"d5b86f9f-0b7a-5415-8f7e-cb5ee8826df2","body":"At the apex of the command floor stood Professor Arthur Sterling.","reuse":true,"previous_version_id":"f3b658fa-4ca5-4d0d-bfd2-93e4abd90f1c","parent_version_ids":["f3b658fa-4ca5-4d0d-bfd2-93e4abd90f1c"],"old_positions":[5],"change_type":"rewrite"},{"position":5,"unit_id":"57df8982-356b-520f-92aa-a1121b989e3e","body":"As General Director of the Geneva Next-Generation Collider, he had spent decades learning that high-energy physics was not practiced in chalk alone. Science at this scale required sovereign funding, cryogenic plants, procurement schedules, radiation protocols, and political oversight. The machines demanded micrometer tolerances and budgets in the hundreds of billions.","reuse":false,"previous_version_id":"e1d54afd-e2bc-4523-83af-4f5e3b2f671c","parent_version_ids":["e1d54afd-e2bc-4523-83af-4f5e3b2f671c"],"old_positions":[6],"change_type":"rewrite"},{"position":6,"unit_id":"6da615ef-05f0-5c45-a6e5-e436d2f7e639","body":"A theory did not survive because it was elegant.","reuse":true,"previous_version_id":"c2ca133c-462d-406c-8065-8e627dedf33f","parent_version_ids":["c2ca133c-462d-406c-8065-8e627dedf33f"],"old_positions":[7],"change_type":"rewrite"},{"position":7,"unit_id":"0cc54b6f-9025-5ed7-af67-07a94be4e5e3","body":"It survived because it predicted what the instruments would see.","reuse":true,"previous_version_id":"86513758-dcba-4565-8aaf-f23de0b664ee","parent_version_ids":["86513758-dcba-4565-8aaf-f23de0b664ee"],"old_positions":[8],"change_type":"rewrite"},{"position":8,"unit_id":"29a9f0d5-9f14-5c31-9680-1929631392df","body":"Sterling had built his career around that distinction.","reuse":true,"previous_version_id":"19ae4253-0065-4a87-aa34-cc25d478c1a2","parent_version_ids":["19ae4253-0065-4a87-aa34-cc25d478c1a2"],"old_positions":[9],"change_type":"rewrite"},{"position":9,"unit_id":"39d2858e-e06d-55cc-b01b-728497e7965f","body":"His Epsilon regularization scheme was not a fundamental theory of the vacuum. He would have rejected that description. It was a phenomenological model of how an otherwise divergent effective interaction should saturate before reaching a physically inaccessible regime.","reuse":false,"previous_version_id":"0b91db2e-ddc4-43b4-b724-698e01bd0355","parent_version_ids":["0b91db2e-ddc4-43b4-b724-698e01bd0355"],"old_positions":[10],"change_type":"rewrite"},{"position":10,"unit_id":"db7f6bb6-bfc8-5694-ba8b-3d739242b0b9","body":"In the NGC models, certain effective spatial terms steepened as the interaction coordinate approached a limiting radius. Sterling introduced a regulated form:","reuse":false,"previous_version_id":"e3211f15-aff8-4950-b35f-4dfac9b6d8d6","parent_version_ids":["e3211f15-aff8-4950-b35f-4dfac9b6d8d6"],"old_positions":[11],"change_type":"rewrite"},{"position":11,"unit_id":"393b2060-b7b6-5900-bcc8-e13df7ccbfb2","body":"$$ V_{\\epsilon}(r) \\sim \\frac{1}{r^2+\\epsilon^2} $$","reuse":true,"previous_version_id":"3645f434-1e06-4a2b-96eb-ad3fa345da1c","parent_version_ids":["3645f434-1e06-4a2b-96eb-ad3fa345da1c"],"old_positions":[12],"change_type":"rewrite"},{"position":12,"unit_id":"53f8d7bc-d475-5e85-a94b-be15aa13f01a","body":"Epsilon represented the assumed finite response scale of the underlying vacuum.","reuse":false,"previous_version_id":"58f95ac1-3f85-4bc0-9e7c-8a2b3e01e658","parent_version_ids":["58f95ac1-3f85-4bc0-9e7c-8a2b3e01e658"],"old_positions":[13],"change_type":"rewrite"},{"position":13,"unit_id":"8ec8038c-795f-5b6a-8435-74ce4ea4ef17","body":"The mathematics alone did nothing to the collider.","reuse":true,"previous_version_id":"1f486bbe-001b-4d50-9e9f-6f31b886ff20","parent_version_ids":["1f486bbe-001b-4d50-9e9f-6f31b886ff20"],"old_positions":[14],"change_type":"rewrite"},{"position":14,"unit_id":"4ead67e4-6d10-51cb-a9d7-594059864dcc","body":"The machine did.","reuse":true,"previous_version_id":"59877cae-b007-45ed-a208-e70d95736eac","parent_version_ids":["59877cae-b007-45ed-a208-e70d95736eac"],"old_positions":[15],"change_type":"rewrite"},{"position":15,"unit_id":"2d57319d-af88-50fc-bedc-7fdcf53bb7db","body":"The scheme had been translated into an active control architecture for successive bunch crossings. The maximum-energy experiment would be a five-hundred-millisecond train containing millions of proton-proton interactions. A crossing already recorded could not be altered. Only the conditions of later crossings could.","reuse":false,"previous_version_id":"46a38a69-e37b-5409-af87-37d78ce8e788","parent_version_ids":["46a38a69-e37b-5409-af87-37d78ce8e788"],"old_positions":[16],"change_type":"rewrite"},{"position":16,"unit_id":"cbd904b5-2cd6-5d1a-9d72-0def42ba2932","body":"Detector telemetry from the first interactions would be reconstructed in real time. If the diagnostic layer inferred an approach to the regulated boundary, the controller would adjust conditions for subsequent bunches: RF phase, beam focus, crossing geometry, and currents in the dedicated correction magnets around the interaction region.","reuse":false,"previous_version_id":"86e62f42-c8f8-50be-86a7-2d471ad32b2c","parent_version_ids":["86e62f42-c8f8-50be-86a7-2d471ad32b2c"],"old_positions":[17],"change_type":"rewrite"},{"position":17,"unit_id":"849f3dcd-0c61-5462-8eb6-0621dcbc0d70","body":"The superconducting quadrupoles supplied the slowly varying focusing bias. Fast pulsed correctors and RF phase shifters would alter conditions for later crossings on microsecond timescales. The system was designed to push the experiment toward the edge of Sterling's model without letting the machine cross it.","reuse":false,"previous_version_id":"e1c3ed31-fa6d-504f-b384-8b21c67da127","parent_version_ids":["e1c3ed31-fa6d-504f-b384-8b21c67da127","1fdaa9ee-c6cf-5665-a84a-d8c3d711358e"],"old_positions":[18,19],"change_type":"merge"},{"position":18,"unit_id":"dcf5e9ea-ea40-58ff-b960-2b7e1428760e","body":"Down in the primary operations tier, Sarah Hayes monitored the control loop.","reuse":false,"previous_version_id":"60f7cafb-4575-5081-8200-33bb62083aba","parent_version_ids":["60f7cafb-4575-5081-8200-33bb62083aba"],"old_positions":[20],"change_type":"rewrite"},{"position":19,"unit_id":"d92e0392-d03f-5a13-93f8-71b927fd0b84","body":"As Chief Engineer of Beam Operations, she had little interest in a theory's philosophical appeal. Her universe was latency, stored magnetic energy, cryogenic margin, sensor confidence, actuator authority—and the uncomfortable interval between fault detection and hardware response.","reuse":false,"previous_version_id":"f556ab4d-892c-5ba8-a19e-d5f7e1396e35","parent_version_ids":["f556ab4d-892c-5ba8-a19e-d5f7e1396e35"],"old_positions":[21],"change_type":"rewrite"},{"position":20,"unit_id":"d66e4c0b-6f6a-5e6d-99ee-a29171b0f40f","body":"A mathematical prediction mattered only if the machine survived long enough to measure it.","reuse":true,"previous_version_id":"6b8d22c2-186a-52da-b83f-93a3c2ab834f","parent_version_ids":["6b8d22c2-186a-52da-b83f-93a3c2ab834f"],"old_positions":[22],"change_type":"rewrite"},{"position":21,"unit_id":"2f96d61e-4190-5c96-b9f0-8abb2c082c37","body":"Her primary display tracked beam orbit and luminosity. The secondary showed the fast-control system's status: local timing, magnet current margin, RF synchronization, quench-protection state, and execution latency between diagnostic nodes and the Sector Four experimental inserts.","reuse":false,"previous_version_id":"95cc38d7-29e5-558f-b3cf-8a64e7e204f3","parent_version_ids":["95cc38d7-29e5-558f-b3cf-8a64e7e204f3"],"old_positions":[23],"change_type":"rewrite"},{"position":22,"unit_id":"06161b3c-d634-5cdc-82b5-eecc42ca67bc","body":"Local optical timing remained phase-locked. A stabilized fiber network distributed the master oscillator's signal across the facility; a rubidium reference provided long-term frequency stability.","reuse":false,"previous_version_id":"96408047-b100-5942-9cb9-05dfdcf57e49","parent_version_ids":["96408047-b100-5942-9cb9-05dfdcf57e49"],"old_positions":[24],"change_type":"rewrite"},{"position":23,"unit_id":"26946cc6-83d0-5bd3-bde4-7306aeac6666","body":"Everything was nominal.","reuse":true,"previous_version_id":"c92eef7d-425c-53df-8c44-0fe99cc11802","parent_version_ids":["c92eef7d-425c-53df-8c44-0fe99cc11802"],"old_positions":[25],"change_type":"rewrite"},{"position":24,"unit_id":"f0582951-1be1-5719-aa90-32ba2c3cdf54","body":"That did not reassure her.","reuse":true,"previous_version_id":"7b7504a8-87e6-5f6e-a99e-b18ff52f3069","parent_version_ids":["7b7504a8-87e6-5f6e-a99e-b18ff52f3069"],"old_positions":[26],"change_type":"rewrite"},{"position":25,"unit_id":"b7da8754-d442-5ba4-9d33-5e9f513faf79","body":"Six months earlier, at an internal NGC symposium, Ian Yoo—a twenty-six-year-old topological physicist—had challenged the assumption on which Sterling's control system depended.","reuse":false,"previous_version_id":"cfc68692-34cf-559a-a418-6b7f7bef0608","parent_version_ids":["cfc68692-34cf-559a-a418-6b7f7bef0608"],"old_positions":[27],"change_type":"rewrite"},{"position":26,"unit_id":"0fca7915-65fd-5ef8-9da2-fc251e075663","body":"Ian had not argued that one hundred tera-electron-volts of collision energy should produce dramatic gravitational effects by itself. Standard physics predicted nothing of the kind.","reuse":false,"previous_version_id":"790ed4d8-f9af-5248-8e27-c34c235c8ffb","parent_version_ids":["790ed4d8-f9af-5248-8e27-c34c235c8ffb"],"old_positions":[28],"change_type":"rewrite"},{"position":27,"unit_id":"fb7d2cb5-64aa-5111-8c4b-34c8799bfb09","body":"His concern was not energy alone but the gradient of a collective spatial phase that could emerge under a highly coherent sequence of interactions. If that gradient crossed a critical threshold, the vacuum response might not saturate smoothly.","reuse":false,"previous_version_id":"96f202fe-6fa2-5661-90a9-af4227c9a733","parent_version_ids":["96f202fe-6fa2-5661-90a9-af4227c9a733","653a2157-1c47-501f-99c6-0fe52a567bc6"],"old_positions":[29,30],"change_type":"merge"},{"position":28,"unit_id":"fa40daeb-9c87-56b3-848c-4cd6ab0d10df","body":"It might shear.","reuse":true,"previous_version_id":"7d107e93-59dc-585c-a3a9-6e3d48c3b4f6","parent_version_ids":["7d107e93-59dc-585c-a3a9-6e3d48c3b4f6"],"old_positions":[31],"change_type":"rewrite"},{"position":29,"unit_id":"dd020bc7-108d-5625-b097-961e79cf3e9c","body":"Sterling had considered the proposal speculative.","reuse":true,"previous_version_id":"8f7dda68-b925-5578-87cd-5d2e860effa2","parent_version_ids":["8f7dda68-b925-5578-87cd-5d2e860effa2"],"old_positions":[32],"change_type":"rewrite"},{"position":30,"unit_id":"5fe0e96e-3e50-5615-a582-85d865162609","body":"Sarah had considered it dangerous.","reuse":true,"previous_version_id":"268ba300-a1a8-5d5e-b72a-6e59b22562ac","parent_version_ids":["268ba300-a1a8-5d5e-b72a-6e59b22562ac"],"old_positions":[33],"change_type":"rewrite"},{"position":31,"unit_id":"cd8a1438-6c1f-550e-82d4-e9ece381b832","body":"Then she had read the code.","reuse":true,"previous_version_id":"38180b47-1f6a-5043-9e58-3a54b3e382e5","parent_version_ids":["38180b47-1f6a-5043-9e58-3a54b3e382e5"],"old_positions":[34],"change_type":"rewrite"},{"position":32,"unit_id":"f73574ee-c630-5313-af9c-5c1358733108","body":"Ian's model did not treat a proton bunch containing billions of particles as a single microscopic wavefunction. It used a coarse-grained MSV order parameter over the circulating beam's collective phase-space distribution:","reuse":false,"previous_version_id":"d434ff2d-e88d-5fb5-8c27-0808209de326","parent_version_ids":["d434ff2d-e88d-5fb5-8c27-0808209de326"],"old_positions":[35],"change_type":"rewrite"},{"position":33,"unit_id":"2aac45f3-d446-5b7e-8c53-51420b721a9d","body":"$$ \\Psi_{\\mathrm{MSV}} = R e^{iS/\\hbar} $$","reuse":true,"previous_version_id":"c74fa058-726c-5bef-ae68-ca8f04259e2b","parent_version_ids":["c74fa058-726c-5bef-ae68-ca8f04259e2b"],"old_positions":[36],"change_type":"rewrite"},{"position":34,"unit_id":"a8018b9c-5f63-597d-aaff-294f94b3d667","body":"For an imposed azimuthal phase,","reuse":true,"previous_version_id":"14aad220-a0ad-5a0d-b437-9aeee06e6fcf","parent_version_ids":["14aad220-a0ad-5a0d-b437-9aeee06e6fcf"],"old_positions":[38],"change_type":"rewrite"},{"position":35,"unit_id":"9a89e64e-51ba-5fdd-b7f4-80318ef42261","body":"$$ S = n\\hbar\\phi $$","reuse":true,"previous_version_id":"253259ad-ab08-5d72-8585-b7e4946e8b22","parent_version_ids":["253259ad-ab08-5d72-8585-b7e4946e8b22"],"old_positions":[39],"change_type":"rewrite"},{"position":36,"unit_id":"487fe498-36d5-5cb4-a091-2e89cc83c638","body":"the phase-kinetic contribution scaled as:","reuse":false,"previous_version_id":"d08cefef-233c-598f-b505-6eebbac1df85","parent_version_ids":["d08cefef-233c-598f-b505-6eebbac1df85"],"old_positions":[40],"change_type":"rewrite"},{"position":37,"unit_id":"2064be29-8a1a-57e6-901e-2857a72c369b","body":"$$ \\frac{(\\nabla S)^2}{2m} \\propto \\frac{1}{r^2} $$","reuse":true,"previous_version_id":"77738a8c-bd6b-569e-846a-2369deff8b88","parent_version_ids":["77738a8c-bd6b-569e-846a-2369deff8b88"],"old_positions":[41],"change_type":"rewrite"},{"position":38,"unit_id":"38116b89-5957-5d0e-a7c9-8e5be9b3a025","body":"To impose that winding on the collective field, Ian proposed a dedicated experimental insert combining skew-quadrupole correctors, a solenoidal section, and RF phase shifters.","reuse":false,"previous_version_id":"f1fc998c-6347-5991-9fd8-132d1a6102fc","parent_version_ids":["f1fc998c-6347-5991-9fd8-132d1a6102fc"],"old_positions":[42],"change_type":"rewrite"},{"position":39,"unit_id":"346b796e-0908-5749-8df6-bda8bbde9fe0","body":"If the native MSV potential developed a leading attractive divergence proportional to -1/r^2, he proposed a controlled phase contribution with matching asymptotic structure and amplitude, but the opposite sign.","reuse":false,"previous_version_id":"eaee51bf-3cc7-5e4a-9494-eab5b6a4f005","parent_version_ids":["eaee51bf-3cc7-5e4a-9494-eab5b6a4f005"],"old_positions":[44],"change_type":"rewrite"},{"position":40,"unit_id":"ecbf8b45-b872-5bfe-b205-75ac8198112e","body":"Not suppression.","reuse":true,"previous_version_id":"954e0ea6-fa72-5179-b0eb-393158fab95f","parent_version_ids":["954e0ea6-fa72-5179-b0eb-393158fab95f"],"old_positions":[45],"change_type":"rewrite"},{"position":41,"unit_id":"743c10b8-65f0-5729-b11d-044e3b0486ff","body":"Cancellation.","reuse":true,"previous_version_id":"481ed781-2e6d-5eb4-a362-9ae9507e9b58","parent_version_ids":["481ed781-2e6d-5eb4-a362-9ae9507e9b58"],"old_positions":[46],"change_type":"rewrite"},{"position":42,"unit_id":"59ad5490-7000-537d-93a1-8a991546d1bf","body":"Sterling had rejected deployment. Ian's model had no independent experimental confirmation, and activating an untested phase-winding architecture inside a one-hundred-tera-electron-volt machine would introduce risks of its own.","reuse":false,"previous_version_id":"3cc086ed-9cb6-5066-9c50-6f71d7af4823","parent_version_ids":["3cc086ed-9cb6-5066-9c50-6f71d7af4823","b86696c1-e1a7-5cec-b89c-4e6f426441bd"],"old_positions":[47,48],"change_type":"merge"},{"position":43,"unit_id":"26cfb273-9245-51fe-a0dd-576521da5d46","body":"He prohibited the solver from the central operational network.","reuse":false,"previous_version_id":"ecb50802-999b-5e75-81b1-51c83c853f01","parent_version_ids":["ecb50802-999b-5e75-81b1-51c83c853f01"],"old_positions":[49],"change_type":"rewrite"},{"position":44,"unit_id":"7e42a389-0e44-5406-ac5c-06e2f3e1226b","body":"Sarah agreed with the prohibition.","reuse":true,"previous_version_id":"27ed112c-3fef-5984-bd41-65c090afc28c","parent_version_ids":["27ed112c-3fef-5984-bd41-65c090afc28c"],"old_positions":[50],"change_type":"rewrite"},{"position":45,"unit_id":"d9f69ed8-0c74-5a23-b693-ab40f19a452d","body":"She was not willing to discard the option.","reuse":false,"previous_version_id":"182299b3-bf1a-569f-a8f4-68690a792b9b","parent_version_ids":["182299b3-bf1a-569f-a8f4-68690a792b9b"],"old_positions":[51],"change_type":"rewrite"},{"position":46,"unit_id":"1e4260be-119b-5427-b9c1-bedd99ba2e05","body":"She had spent three weeks auditing Ian's implementation line by line. She disliked some of its assumptions and found his philosophy rigid. She found no obvious defect in the control logic translating his phase model into hardware commands.","reuse":false,"previous_version_id":"d29d8357-8db2-532c-a894-14cb17efcbda","parent_version_ids":["d29d8357-8db2-532c-a894-14cb17efcbda"],"old_positions":[52],"change_type":"rewrite"},{"position":47,"unit_id":"2ec91275-f9dc-579f-bce2-3714301a4dbb","body":"So she made a compromise Sterling had never authorized.","reuse":true,"previous_version_id":"b48a3194-6ae3-5797-adef-a4f11424d923","parent_version_ids":["b48a3194-6ae3-5797-adef-a4f11424d923"],"old_positions":[53],"change_type":"rewrite"},{"position":48,"unit_id":"4ad57ede-4588-5a40-96a8-198779d90142","body":"Sarah kept Ian's counter-field solver off the central operational network. The compiled build remained in an isolated FPGA sandbox physically attached to the Sector Four experimental insert. It could not take command of the collider.","reuse":false,"previous_version_id":"3e1ef99e-de01-5583-9c17-96d14b43998c","parent_version_ids":["3e1ef99e-de01-5583-9c17-96d14b43998c"],"old_positions":[54],"change_type":"rewrite"},{"position":49,"unit_id":"ad5c72d2-906c-50dd-b994-7dcdecb4ee0f","body":"Dormant.","reuse":true,"previous_version_id":"80afc972-3412-55d5-bc2f-b4926812aa7e","parent_version_ids":["80afc972-3412-55d5-bc2f-b4926812aa7e"],"old_positions":[55],"change_type":"rewrite"},{"position":50,"unit_id":"51bb31ad-5401-5bff-96fc-e7c23a1c8ef6","body":"Local.","reuse":true,"previous_version_id":"96cf3d70-d381-5842-befb-6f8b6f5d6279","parent_version_ids":["96cf3d70-d381-5842-befb-6f8b6f5d6279"],"old_positions":[56],"change_type":"rewrite"},{"position":51,"unit_id":"a88917e6-b100-52de-b5c1-1b73f8c71708","body":"Inaccessible from the central network without her authorization.","reuse":true,"previous_version_id":"e2428797-f4fe-528c-98d9-1047b8d3f907","parent_version_ids":["e2428797-f4fe-528c-98d9-1047b8d3f907"],"old_positions":[57],"change_type":"rewrite"},{"position":52,"unit_id":"1cff7c09-4a2b-5ac3-a5d0-11acb28203ec","body":"A fire extinguisher for a fire she did not believe existed.","reuse":true,"previous_version_id":"8251d0f0-32a5-5271-98e9-7501a69db028","parent_version_ids":["8251d0f0-32a5-5271-98e9-7501a69db028"],"old_positions":[58],"change_type":"rewrite"},{"position":53,"unit_id":"ec8c6949-2604-563e-ba1b-8216a2bcd89d","body":"Sterling's voice broke through the quiet operational noise.","reuse":true,"previous_version_id":"d1f334e3-de6e-5b09-a419-86eb914daf43","parent_version_ids":["d1f334e3-de6e-5b09-a419-86eb914daf43"],"old_positions":[59],"change_type":"rewrite"},{"position":54,"unit_id":"96cd12f0-a854-5c11-8971-d46fec62dd13","body":"\"Status.\"","reuse":true,"previous_version_id":"26ad8fa3-401b-5abc-94ad-e3bb2266f1d5","parent_version_ids":["26ad8fa3-401b-5abc-94ad-e3bb2266f1d5"],"old_positions":[60],"change_type":"rewrite"},{"position":55,"unit_id":"a57713ee-ba5c-554a-b696-8f0879325d15","body":"Sarah brought the machine-health panel to the foreground.","reuse":true,"previous_version_id":"0784a598-e512-5b31-95c6-7950db2bff43","parent_version_ids":["0784a598-e512-5b31-95c6-7950db2bff43"],"old_positions":[61],"change_type":"rewrite"},{"position":56,"unit_id":"0e03951e-0927-5db6-827d-361b852348bc","body":"\"Cryogenics nominal. Cold mass stable. Sixteen-tesla niobium-tin dipoles within operating margin. Optical timing locked. Beam orbit within tolerance. Epsilon feedback armed.\"","reuse":false,"previous_version_id":"536a7928-86c9-5e63-b582-8ca4b696064f","parent_version_ids":["536a7928-86c9-5e63-b582-8ca4b696064f"],"old_positions":[62],"change_type":"rewrite"},{"position":57,"unit_id":"fd9d9291-817f-557f-a089-8308e2d1ef4f","body":"At the neighboring console, a junior beam technician checked the luminosity ramp.","reuse":false,"previous_version_id":"e1b8f3e4-79d6-5454-bd41-0e7261d4fa3a","parent_version_ids":["e1b8f3e4-79d6-5454-bd41-0e7261d4fa3a"],"old_positions":[63],"change_type":"rewrite"},{"position":58,"unit_id":"3261a097-3100-5849-9a78-e66441b7d86d","body":"\"Approaching one hundred tera-electron-volts center-of-mass at the primary interaction point.\"","reuse":true,"previous_version_id":"971e520a-cd48-5fb2-8fba-f4a25e6fdec5","parent_version_ids":["971e520a-cd48-5fb2-8fba-f4a25e6fdec5"],"old_positions":[64],"change_type":"rewrite"},{"position":59,"unit_id":"a3061736-6048-58d1-aaa7-d0a4fa44e6d0","body":"Sterling stepped to the railing. The run would test whether the predicted saturation boundary appeared in the data. He had authorized a five-hundred-millisecond high-luminosity window.","reuse":false,"previous_version_id":"e7f1b7e6-fa13-541a-9a3e-58a6a7ecf82d","parent_version_ids":["e7f1b7e6-fa13-541a-9a3e-58a6a7ecf82d","91a325f7-bf5e-595d-a94d-3f19fd05a61b","bdb9120e-dc8b-5916-b8f8-1a17d5175628"],"old_positions":[65,66,67],"change_type":"merge"},{"position":60,"unit_id":"9f301a03-45b5-543b-add8-047b98971861","body":"Long enough to approach the model's edge.","reuse":false,"previous_version_id":"bfda0a66-146f-5977-989b-881fe0852a04","parent_version_ids":["bfda0a66-146f-5977-989b-881fe0852a04"],"old_positions":[68],"change_type":"rewrite"},{"position":61,"unit_id":"301ebc2e-285d-5dd3-aecf-837eb4a64a24","body":"Short enough, according to every accepted simulation, for the controller to keep it there.","reuse":true,"previous_version_id":"5892e116-90e2-50bd-b766-6450adfc56f0","parent_version_ids":["5892e116-90e2-50bd-b766-6450adfc56f0"],"old_positions":[69],"change_type":"rewrite"},{"position":62,"unit_id":"04c635ff-3cd7-5cfb-ba97-76035c9b37ea","body":"\"The reconstructed residuals should remain inside the finite envelope throughout the bunch train,\" Sterling said. \"If the model is correct, the response will saturate before the machine reaches an undefined regime.\"","reuse":true,"previous_version_id":"176afec5-edaf-5c2a-bd14-525d1a4b4f2a","parent_version_ids":["176afec5-edaf-5c2a-bd14-525d1a4b4f2a"],"old_positions":[70],"change_type":"rewrite"},{"position":63,"unit_id":"f3af30cc-03ad-51ec-b8f9-49d48ecdd2b2","body":"Sarah glanced at the Sector Four local-control panel.","reuse":false,"previous_version_id":"da9a33a5-4505-5fef-b426-e3b9a60a24a6","parent_version_ids":["da9a33a5-4505-5fef-b426-e3b9a60a24a6"],"old_positions":[71],"change_type":"rewrite"},{"position":64,"unit_id":"e9effa13-3a64-5585-a9fa-b383615e2bab","body":"SANDBOX: INACTIVE","reuse":true,"previous_version_id":"bf564a6e-ee99-5f55-9aab-9d80c47bddb9","parent_version_ids":["bf564a6e-ee99-5f55-9aab-9d80c47bddb9"],"old_positions":[72],"change_type":"rewrite"},{"position":65,"unit_id":"4b73ef6d-ffc7-5cd9-9727-0c8a4efe19ec","body":"Ian's solver was still there.","reuse":true,"previous_version_id":"e6fd4d22-eff2-5d16-a54f-a62faa64f592","parent_version_ids":["e6fd4d22-eff2-5d16-a54f-a62faa64f592"],"old_positions":[73],"change_type":"rewrite"},{"position":66,"unit_id":"77473296-22bf-5056-afa7-1a103d141b89","body":"She returned to the primary console.","reuse":false,"previous_version_id":"72d5c6cc-b6a6-5edf-ad37-9712df246cdd","parent_version_ids":["72d5c6cc-b6a6-5edf-ad37-9712df246cdd"],"old_positions":[74],"change_type":"rewrite"},{"position":67,"unit_id":"8df02aca-907d-5b75-842e-6f2da1b9164e","body":"\"Final injection sequence ready.\"","reuse":true,"previous_version_id":"2fca9eff-747d-510b-90a7-792e0e923a40","parent_version_ids":["2fca9eff-747d-510b-90a7-792e0e923a40"],"old_positions":[75],"change_type":"rewrite"},{"position":68,"unit_id":"6af960ec-3d47-5f58-9385-8f4822d6e123","body":"Sterling nodded.","reuse":true,"previous_version_id":"2ef8a593-bc1a-587c-b327-18ae4bfc6b24","parent_version_ids":["2ef8a593-bc1a-587c-b327-18ae4bfc6b24"],"old_positions":[76],"change_type":"rewrite"},{"position":69,"unit_id":"0a267454-b96d-5571-88a4-c2e3ebd1d7be","body":"\"Proceed.\"","reuse":true,"previous_version_id":"e570a57d-cc05-5560-855c-53242802dcbb","parent_version_ids":["e570a57d-cc05-5560-855c-53242802dcbb"],"old_positions":[77],"change_type":"rewrite"},{"position":70,"unit_id":"2326540e-b382-5b2a-a939-73bc76d3999a","body":"Sarah authorized the ramp.","reuse":true,"previous_version_id":"f47e07c1-c140-5e90-a88c-fcb30a657249","parent_version_ids":["f47e07c1-c140-5e90-a88c-fcb30a657249"],"old_positions":[78],"change_type":"rewrite"},{"position":71,"unit_id":"7b0bb846-250b-550f-84c3-b6f032ec427e","body":"\"RF cavities at operational voltage.\"","reuse":true,"previous_version_id":"e65078d6-fb83-5ec3-9114-8de2c7a99cca","parent_version_ids":["e65078d6-fb83-5ec3-9114-8de2c7a99cca"],"old_positions":[79],"change_type":"rewrite"},{"position":72,"unit_id":"2437d970-3c49-565f-b103-70c6578f8fe3","body":"The automated collision sequence took control.","reuse":true,"previous_version_id":"23a237e9-d786-5c22-a3a8-cfedb1d1f652","parent_version_ids":["23a237e9-d786-5c22-a3a8-cfedb1d1f652"],"old_positions":[80],"change_type":"rewrite"},{"position":73,"unit_id":"10b8bd9f-5d3a-5364-8e5c-441e677a0851","body":"\"Crossing in three.\"","reuse":true,"previous_version_id":"45107eaa-2b87-5398-91d1-1962581c732b","parent_version_ids":["45107eaa-2b87-5398-91d1-1962581c732b"],"old_positions":[81],"change_type":"rewrite"},{"position":74,"unit_id":"e8bad7b0-cd15-5d73-859e-fe0c933d6075","body":"On the primary displays, the two beam trajectories converged.","reuse":true,"previous_version_id":"e12d5604-7e51-5b4a-badf-3902ba90abe9","parent_version_ids":["e12d5604-7e51-5b4a-badf-3902ba90abe9"],"old_positions":[82],"change_type":"rewrite"},{"position":75,"unit_id":"c831cb8d-93c4-58bb-b0a7-07d5a555b9ae","body":"\"Two.\"","reuse":true,"previous_version_id":"272c8274-258f-50d0-8e4b-0324c6c42fc8","parent_version_ids":["272c8274-258f-50d0-8e4b-0324c6c42fc8"],"old_positions":[83],"change_type":"rewrite"},{"position":76,"unit_id":"680b3247-6815-5e61-a5a8-bc781fb82315","body":"The Epsilon controller entered monitoring mode.","reuse":true,"previous_version_id":"1e69cccf-e4c7-5715-8777-f20233efc422","parent_version_ids":["1e69cccf-e4c7-5715-8777-f20233efc422"],"old_positions":[84],"change_type":"rewrite"},{"position":77,"unit_id":"93360e17-78e2-5a12-86b5-3da76756b317","body":"\"One.\"","reuse":true,"previous_version_id":"86d47ca5-925f-5450-98d0-dadf4414ca38","parent_version_ids":["86d47ca5-925f-5450-98d0-dadf4414ca38"],"old_positions":[85],"change_type":"rewrite"},{"position":78,"unit_id":"f18e40d8-b71b-5f79-ad4f-3cdffe8208fb","body":"Sarah watched the latency counters.","reuse":true,"previous_version_id":"f3380660-a994-559b-8fbb-a4ae16aa6392","parent_version_ids":["f3380660-a994-559b-8fbb-a4ae16aa6392"],"old_positions":[86],"change_type":"rewrite"},{"position":79,"unit_id":"06995691-c14c-5da2-9b73-2bf2a81f2898","body":"\"Mark.\"","reuse":true,"previous_version_id":"260d6537-cc47-5dd7-a061-528c14f4fd34","parent_version_ids":["260d6537-cc47-5dd7-a061-528c14f4fd34"],"old_positions":[87],"change_type":"rewrite"}],"omitted":[{"unit_id":"56e797f8-85b5-5fdc-bb13-05c20c95f891","old_position":4,"version_id":"c91899f4-cf6a-49d1-8dbf-b686d952b233","reason":"merged_into_approved_block"},{"unit_id":"e2fbbf47-018a-5c12-a6f9-c3fdcb0eb89b","old_position":19,"version_id":"1fdaa9ee-c6cf-5665-a84a-d8c3d711358e","reason":"merged_into_approved_block"},{"unit_id":"e22fe500-0bfa-5924-b526-d954c66c7449","old_position":30,"version_id":"653a2157-1c47-501f-99c6-0fe52a567bc6","reason":"merged_into_approved_block"},{"unit_id":"356c6b88-3256-51cb-a3e0-4562caef770b","old_position":37,"version_id":"b6a33c69-61a0-5713-8729-775166db323d","reason":"omitted_by_approved_scene"},{"unit_id":"60c654a4-9ed1-5c75-bb92-07e80fbcfacc","old_position":43,"version_id":"29ffa383-71aa-5b8f-8114-4eb40e7df724","reason":"omitted_by_approved_scene"},{"unit_id":"3bfad606-54c7-5037-bd6b-97faf6a28d76","old_position":48,"version_id":"b86696c1-e1a7-5cec-b89c-4e6f426441bd","reason":"merged_into_approved_block"},{"unit_id":"bef311c0-5a29-5ac2-9b30-63ae4cff2367","old_position":66,"version_id":"91a325f7-bf5e-595d-a94d-3f19fd05a61b","reason":"merged_into_approved_block"},{"unit_id":"4fed83d8-eb9a-59cf-b1e3-c4ed7fcae711","old_position":67,"version_id":"bdb9120e-dc8b-5916-b8f8-1a17d5175628","reason":"merged_into_approved_block"}]}$payload$::jsonb;
  snap uuid := '66cda81f-6a3a-4c8b-a226-c7169ffd2710';
  scene uuid := '55b46292-0335-5fbc-ab9e-baa44d3bea70';
  project uuid := '707e3ae1-0817-467a-bb42-5401c646151e';
  version_code text := 'PRO-CH1-SC1-RESTART-D1';
  backup_code text := 'PRE_PRO_CH1_SC1_RESTART_D1';
  doc_id text := 'quantum-vibration-novel-en-act-2';
  approved text;
  old_doc jsonb;
  old_scene jsonb;
  new_doc jsonb;
  new_scene jsonb;
  reader_paragraphs jsonb := '[]'::jsonb;
  new_versions jsonb := '[]'::jsonb;
  q jsonb;
  parent_id text;
  pv_id uuid;
  pv_no integer;
  body text;
  text_after text;
  reader_after text;
  backup_id uuid;
  old_map jsonb;
  old_snapshot jsonb;
  all_snapshot_maps jsonb;
  other_documents_hash text;
  outside_map_hash text;
  old_versions_hash text;
  old_version_ids uuid[];
  old_lineages_hash text;
  existing_lineage_ids uuid[];
  content_units_hash text;
  scene_matrices_hash text;
  backup_map_hash text;
  working_map_hash text;
  new_count integer := 0;
  reuse_count integer := 0;
  edge_count integer := 0;
  n integer;
  words integer;
  display_math integer;
  seq integer;
BEGIN
  approved := p->>'approved';
  IF encode(sha256(convert_to(approved,'UTF8')),'hex') IS DISTINCT FROM p->>'expected_sha256'
     OR octet_length(approved) <> 7955 THEN
    RAISE EXCEPTION 'Approved payload bytes/hash mismatch';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(scene::text,0));
  SELECT data INTO STRICT old_doc FROM public.novel_documents WHERE id=doc_id AND slug=doc_id FOR UPDATE;
  SELECT to_jsonb(s) INTO STRICT old_snapshot FROM public.revision_snapshots s WHERE id=snap FOR UPDATE;
  PERFORM 1 FROM public.revision_content_map WHERE snapshot_id=snap AND (parent_unit_id=scene OR unit_id=scene) FOR UPDATE;
  IF old_snapshot IS DISTINCT FROM p->'expected_snapshot' OR old_snapshot->>'state' <> 'draft' THEN
    RAISE EXCEPTION 'Working snapshot changed since preflight';
  END IF;
  IF md5(old_doc::text) IS DISTINCT FROM p->>'expected_document_md5' THEN
    RAISE EXCEPTION 'Reader document changed since preflight';
  END IF;
  old_scene := old_doc#>'{chapters,1,scenes,0}';
  IF old_scene IS DISTINCT FROM p->'expected_scene'
     OR old_doc->>'title' <> 'PROLOGUE: THE NODE'
     OR old_doc#>>'{chapters,1,title}' <> 'Chapter 1: The Cathedral in the Molasse'
     OR old_scene->>'id' <> 'b48a4f04' THEN
    RAISE EXCEPTION 'Reader scene identity/source mismatch';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.content_units WHERE id=scene AND project_id=project AND source_path='act-2/ch-2/sc-1') THEN
    RAISE EXCEPTION 'Revision scene identity mismatch';
  END IF;
  SELECT jsonb_agg(to_jsonb(m) ORDER BY m.position) INTO old_map FROM public.revision_content_map m
    WHERE m.snapshot_id=snap AND m.parent_unit_id=scene;
  IF old_map IS DISTINCT FROM p->'expected_map'
     OR (SELECT to_jsonb(m) FROM public.revision_content_map m WHERE snapshot_id=snap AND unit_id=scene)
        IS DISTINCT FROM p->'expected_scene_map' THEN
    RAISE EXCEPTION 'Working source map changed since preflight';
  END IF;
  SELECT string_agg(pv.body_markdown,E'\n\n' ORDER BY m.position)||E'\n\n' INTO text_after
    FROM public.revision_content_map m JOIN public.paragraph_versions pv ON pv.id=m.paragraph_version_id
    WHERE m.snapshot_id=snap AND m.parent_unit_id=scene AND m.is_included;
  IF text_after IS DISTINCT FROM replace(old_scene#>>'{paragraphs,0,versions,v_en,content}', chr(92)||'n'||chr(92)||'n', E'\n\n') THEN
    RAISE EXCEPTION 'Reader and working source texts disagree';
  END IF;
  IF EXISTS(SELECT 1 FROM public.revision_snapshots WHERE project_id=project AND code=backup_code) THEN
    RAISE EXCEPTION 'Application checkpoint already exists; do not apply twice';
  END IF;

  -- Read-set evidence for existing assets outside this scene.
  SELECT jsonb_agg(jsonb_build_object('snapshot',to_jsonb(s),'map_hash',
      (SELECT md5(coalesce(string_agg(to_jsonb(m)::text,'|' ORDER BY unit_id),'')) FROM public.revision_content_map m WHERE m.snapshot_id=s.id)) ORDER BY s.id)
    INTO all_snapshot_maps FROM public.revision_snapshots s WHERE s.project_id=project AND s.id<>snap;
  SELECT md5(coalesce(string_agg(to_jsonb(m)::text,'|' ORDER BY unit_id),'')) INTO outside_map_hash
    FROM public.revision_content_map m WHERE snapshot_id=snap AND parent_unit_id IS DISTINCT FROM scene AND unit_id<>scene;
  SELECT md5(coalesce(string_agg(to_jsonb(d)::text,'|' ORDER BY id),'')) INTO other_documents_hash
    FROM public.novel_documents d WHERE id<>doc_id;
  SELECT array_agg(id ORDER BY id),md5(string_agg(to_jsonb(v)::text,'|' ORDER BY id))
    INTO old_version_ids,old_versions_hash FROM public.paragraph_versions v;
  SELECT array_agg(id ORDER BY id),md5(coalesce(string_agg(to_jsonb(l)::text,'|' ORDER BY id),''))
    INTO existing_lineage_ids,old_lineages_hash FROM public.paragraph_version_lineage l;
  SELECT md5(string_agg(to_jsonb(u)::text,'|' ORDER BY id)) INTO content_units_hash FROM public.content_units u;
  SELECT md5(string_agg(to_jsonb(m)::text,'|' ORDER BY snapshot_id,scene_unit_id)) INTO scene_matrices_hash FROM public.scene_matrices m;

  -- Preserve a full immutable pre-application mapping checkpoint, with no manuscript duplication.
  backup_id := gen_random_uuid();
  INSERT INTO public.revision_snapshots
    (id,project_id,code,name,description,state,base_snapshot_id,manifest_hash,word_count,snapshot_kind,is_canonical,is_current_release,is_primary_working)
    VALUES (backup_id,project,backup_code,'Before PRO-CH1-SC1-RESTART-D1',
      'Exact mapping checkpoint before approved Scene 1 replacement; no editorial status changes.',
      'draft',snap,old_snapshot->>'manifest_hash',(old_snapshot->>'word_count')::integer,'audit',false,false,false);
  INSERT INTO public.revision_content_map
    (snapshot_id,unit_id,parent_unit_id,position,paragraph_version_id,is_included,title_override,metadata_override)
    SELECT backup_id,unit_id,parent_unit_id,position,paragraph_version_id,is_included,title_override,metadata_override
      FROM public.revision_content_map WHERE snapshot_id=snap;
  SELECT md5(string_agg((to_jsonb(m)-'snapshot_id')::text,'|' ORDER BY unit_id)) INTO backup_map_hash
    FROM public.revision_content_map m WHERE snapshot_id=backup_id;
  SELECT md5(string_agg((to_jsonb(m)-'snapshot_id')::text,'|' ORDER BY unit_id)) INTO working_map_hash
    FROM public.revision_content_map m WHERE snapshot_id=snap;
  IF backup_map_hash IS DISTINCT FROM working_map_hash THEN RAISE EXCEPTION 'Checkpoint copy mismatch'; END IF;
  UPDATE public.revision_snapshots SET state='locked',locked_at=now(),updated_at=now() WHERE id=backup_id;

  -- Reuse exact blocks; append new immutable versions only for changed approved blocks.
  -- Non-selected original units stay in the draft as excluded; all prior versions are retained.
  UPDATE public.revision_content_map SET is_included=false,position=100000+position
    WHERE snapshot_id=snap AND parent_unit_id=scene;
  FOR q IN SELECT value FROM jsonb_array_elements(p->'plan') LOOP
    body := q->>'body';
    IF (q->>'reuse')::boolean THEN
      pv_id := (q->>'previous_version_id')::uuid;
      IF (SELECT body_markdown FROM public.paragraph_versions WHERE id=pv_id) IS DISTINCT FROM body THEN
        RAISE EXCEPTION 'Reused block content mismatch at %',q->>'position';
      END IF;
      reuse_count := reuse_count+1;
    ELSE
      pv_id := gen_random_uuid();
      SELECT coalesce(max(version_no),0)+1 INTO pv_no FROM public.paragraph_versions WHERE paragraph_unit_id=(q->>'unit_id')::uuid;
      SELECT count(*) INTO words FROM regexp_split_to_table(body,E'\\s+') w WHERE w<>'' AND w<>'$$';
      INSERT INTO public.paragraph_versions
        (id,paragraph_unit_id,version_no,body_markdown,body_hash,base_version_id,change_type,change_note,word_count)
        VALUES(pv_id,(q->>'unit_id')::uuid,pv_no,body,encode(sha256(convert_to(body,'UTF8')),'hex'),
          (q->>'previous_version_id')::uuid,q->>'change_type',
          version_code||'; exact approved Scene 1 block '||(q->>'position')||'; no additional editorial changes',words);
      seq := 0;
      FOR parent_id IN SELECT value FROM jsonb_array_elements_text(q->'parent_version_ids') LOOP
        seq := seq+1;
        INSERT INTO public.paragraph_version_lineage(child_version_id,parent_version_id,relation_type,sequence_no,note)
          VALUES(pv_id,parent_id::uuid,CASE WHEN q->>'change_type'='merge' THEN 'merged_from' ELSE 'rewritten_from' END,
            seq,version_code||'; approved full-scene source mapping');
        edge_count := edge_count+1;
      END LOOP;
      new_count := new_count+1;
      new_versions := new_versions||jsonb_build_array(jsonb_build_object('id',pv_id,'unit_id',q->>'unit_id','position',(q->>'position')::integer));
    END IF;
    UPDATE public.revision_content_map SET position=(q->>'position')::integer,paragraph_version_id=pv_id,is_included=true
      WHERE snapshot_id=snap AND unit_id=(q->>'unit_id')::uuid AND parent_unit_id=scene;
    GET DIAGNOSTICS n=ROW_COUNT;
    IF n<>1 THEN RAISE EXCEPTION 'Target paragraph map missing'; END IF;
    reader_paragraphs := reader_paragraphs||jsonb_build_array(jsonb_build_object(
      'id',q->>'unit_id','activeVersion',version_code,
      'versions',jsonb_build_object(version_code,jsonb_build_object('version',version_code,'content',body,
        'createdAt',now(),'note','Exact approved manuscript; revision version '||pv_id::text)),
      'revisionVersionId',pv_id));
  END LOOP;
  IF new_count<>32 OR reuse_count<>47 OR edge_count<>38 THEN RAISE EXCEPTION 'Version/lineage count mismatch'; END IF;

  UPDATE public.revision_content_map SET metadata_override=coalesce(metadata_override,'{}'::jsonb)||jsonb_build_object(
    'editorial_version',version_code,'approved_sha256',p->>'expected_sha256','content_blocks',79,'prose_blocks',75,
    'display_equations',4,'word_count_rule','whitespace excluding standalone $$','approved_word_count',1089,
    'pre_application_snapshot_id',backup_id,'applied_at',now())
    WHERE snapshot_id=snap AND unit_id=scene;

  -- Only the chosen reader Scene changes. Retain its complete previous JSON in-scene.
  new_scene := old_scene||jsonb_build_object(
    'paragraphs',reader_paragraphs,
    'publicationHistory',coalesce(old_scene->'publicationHistory','[]'::jsonb)||jsonb_build_array(jsonb_build_object(
      'before_editorial_version',version_code,'preserved_at',now(),'scene',old_scene,'revision_snapshot_id',backup_id)),
    'publication',jsonb_build_object('editorial_version',version_code,'approved_sha256',p->>'expected_sha256',
      'revision_scene_id',scene,'working_snapshot_id',snap,'applied_at',now()));
  new_doc := jsonb_set(old_doc,'{chapters,1,scenes,0}',new_scene,false);
  IF new_doc#-'{chapters,1,scenes,0}' IS DISTINCT FROM old_doc#-'{chapters,1,scenes,0}' THEN
    RAISE EXCEPTION 'Outside-scene document mutation';
  END IF;
  IF (new_scene-'paragraphs'-'publicationHistory'-'publication') IS DISTINCT FROM (old_scene-'paragraphs') THEN
    RAISE EXCEPTION 'Scene title/identity mutation';
  END IF;
  UPDATE public.novel_documents SET data=new_doc,updated_at=now() WHERE id=doc_id;
  -- Aggregate metadata is recalculated; no global release flag is changed.
  UPDATE public.revision_snapshots SET
    word_count=(SELECT coalesce(sum(v.word_count),0) FROM public.revision_content_map m JOIN public.paragraph_versions v ON v.id=m.paragraph_version_id WHERE m.snapshot_id=snap AND m.is_included),
    manifest_hash=(SELECT encode(sha256(convert_to(string_agg(m.unit_id::text||':'||coalesce(v.body_hash,'none')||':'||m.position::text,'|' ORDER BY m.parent_unit_id NULLS FIRST,m.position,m.unit_id),'UTF8')),'hex')
      FROM public.revision_content_map m LEFT JOIN public.paragraph_versions v ON v.id=m.paragraph_version_id WHERE m.snapshot_id=snap),
    updated_at=now() WHERE id=snap;

  -- Read the stored records, not the input payload, for exact acceptance checks.
  SELECT string_agg(v.body_markdown,E'\n\n' ORDER BY m.position)||E'\n',count(*),count(*) FILTER(WHERE v.body_markdown LIKE '$$ % $$')
    INTO text_after,n,display_math FROM public.revision_content_map m JOIN public.paragraph_versions v ON v.id=m.paragraph_version_id
    WHERE m.snapshot_id=snap AND m.parent_unit_id=scene AND m.is_included;
  SELECT string_agg(x.value#>>ARRAY['versions',x.value->>'activeVersion','content'],E'\n\n' ORDER BY x.ordinality)||E'\n'
    INTO reader_after FROM public.novel_documents d CROSS JOIN LATERAL jsonb_array_elements(d.data#>'{chapters,1,scenes,0,paragraphs}') WITH ORDINALITY x(value,ordinality)
    WHERE d.id=doc_id;
  IF text_after IS DISTINCT FROM approved OR reader_after IS DISTINCT FROM approved OR n<>79 OR display_math<>4 THEN
    RAISE EXCEPTION 'Stored manuscript/paragraph/equation mismatch';
  END IF;
  IF (SELECT md5(string_agg(to_jsonb(v)::text,'|' ORDER BY id)) FROM public.paragraph_versions v WHERE id=ANY(old_version_ids)) IS DISTINCT FROM old_versions_hash
     OR (SELECT md5(coalesce(string_agg(to_jsonb(l)::text,'|' ORDER BY id),'')) FROM public.paragraph_version_lineage l WHERE id=ANY(existing_lineage_ids)) IS DISTINCT FROM old_lineages_hash
     OR (SELECT md5(string_agg(to_jsonb(u)::text,'|' ORDER BY id)) FROM public.content_units u) IS DISTINCT FROM content_units_hash
     OR (SELECT md5(string_agg(to_jsonb(m)::text,'|' ORDER BY snapshot_id,scene_unit_id)) FROM public.scene_matrices m) IS DISTINCT FROM scene_matrices_hash THEN
    RAISE EXCEPTION 'Existing version/lineage/unit/matrix modified';
  END IF;
  IF (SELECT md5(coalesce(string_agg(to_jsonb(m)::text,'|' ORDER BY unit_id),'')) FROM public.revision_content_map m
      WHERE snapshot_id=snap AND parent_unit_id IS DISTINCT FROM scene AND unit_id<>scene) IS DISTINCT FROM outside_map_hash
     OR (SELECT md5(coalesce(string_agg(to_jsonb(d)::text,'|' ORDER BY id),'')) FROM public.novel_documents d WHERE id<>doc_id) IS DISTINCT FROM other_documents_hash THEN
    RAISE EXCEPTION 'Outside-scene map/document modified';
  END IF;
  IF (SELECT jsonb_agg(jsonb_build_object('snapshot',to_jsonb(s),'map_hash',
      (SELECT md5(coalesce(string_agg(to_jsonb(m)::text,'|' ORDER BY unit_id),'')) FROM public.revision_content_map m WHERE m.snapshot_id=s.id)) ORDER BY s.id)
      FROM public.revision_snapshots s WHERE s.project_id=project AND s.id NOT IN (snap,backup_id)) IS DISTINCT FROM all_snapshot_maps THEN
    RAISE EXCEPTION 'Existing baseline/archive changed';
  END IF;
  PERFORM set_config('scene_apply.result',jsonb_build_object(
    'version',version_code,'target_scene',scene,'reader_scene','b48a4f04','working_snapshot',snap,
    'backup_snapshot',backup_id,'backup_code',backup_code,'previous_map_copy_md5',backup_map_hash,
    'content_blocks',n,'display_equations',display_math,'new_versions',new_count,'reused_versions',reuse_count,
    'lineage_edges',edge_count,'new_version_ids',new_versions,'sha256',encode(sha256(convert_to(text_after,'UTF8')),'hex'),
    'reader_sha256',encode(sha256(convert_to(reader_after,'UTF8')),'hex'),
    'outside_scene_changes',0,'existing_versions_preserved',true,'locked_baselines_preserved',true,
    'other_documents_md5',other_documents_hash,'outside_working_map_md5',outside_map_hash,
    'manuscript_match',true,'applied_at',now())::text,true);
END;
$apply$;
SET CONSTRAINTS ALL IMMEDIATE;
SELECT current_setting('scene_apply.result')::jsonb AS result;
COMMIT;
